import {Study,STEP} from './simulation.js';
const canvas=document.querySelector('#scene'),ctx=canvas.getContext('2d'),sim=new Study();
const sprites=await Promise.all([1,4,7,11,18].map(i=>new Promise(resolve=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>resolve(null);im.src=`assets/leaf-${String(i).padStart(2,'0')}.png`})));
// Pre-tinted leaf variants preserve texture and alpha without per-frame filters.
const leafTones=sprites.map(im=>{if(!im)return[];return ['rgba(101,123,61,.58)','rgba(147,158,80,.40)','rgba(191,164,87,.18)'].map(color=>{const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const g=c.getContext('2d');g.drawImage(im,0,0);g.globalCompositeOperation='source-atop';g.fillStyle=color;g.fillRect(0,0,c.width,c.height);return c})});
let scale=1,leafScale=1,ox=0,oy=0,width=0,height=0,raf=0,last=null,acc=0,pointer=null,pending=[],previous=null,velocity={x:0,y:0},pulse=0,trail=[];
const media=matchMedia('(prefers-reduced-motion: reduce)');sim.setReduced(media.matches);
function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);const portrait=width<=600&&height>width;scale=Math.min(width/(portrait?700:760),height/(portrait?760:850));leafScale=portrait?1.18:1;ox=(width-900*scale)/2;oy=(height-(portrait?800:715)*scale)/2;previous=null;pending=[];wake()}
function world(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left-ox)/scale,y:(e.clientY-r.top-oy)/scale,t:e.timeStamp}}
function wake(){if(!raf&&!document.hidden)raf=requestAnimationFrame(frame)}
function finish(){if(pointer!==null&&canvas.hasPointerCapture(pointer))canvas.releasePointerCapture(pointer);pointer=null;previous=null;pending=[];velocity={x:0,y:0};wake()}
canvas.addEventListener('pointerdown',e=>{if(pointer!==null||(e.pointerType==='mouse'&&e.button!==0))return;pointer=e.pointerId;canvas.setPointerCapture(pointer);previous=world(e);pending=[];velocity={x:0,y:0};sim.beginGesture();wake()});
canvas.addEventListener('pointermove',e=>{if(e.pointerId!==pointer)return;pending.push(world(e));if(pending.length>64)pending.shift();wake()});
for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,e=>{if(e.pointerId===pointer)finish()});window.addEventListener('blur',finish);
function input(){if(!pending.length)return;const batch=pending.splice(0),a=previous;for(const p of batch){if(previous){const dt=(p.t-previous.t)/1000;if(dt>0&&dt<.1){let vx=(p.x-previous.x)/dt,vy=(p.y-previous.y)/dt,s=Math.min(1,1800/(Math.hypot(vx,vy)||1)),k=1-Math.exp(-dt/.045);velocity.x+=(vx*s-velocity.x)*k;velocity.y+=(vy*s-velocity.y)*k}else velocity={x:0,y:0}}previous=p}if(a&&previous){const distance=Math.hypot(previous.x-a.x,previous.y-a.y),count=Math.max(1,Math.min(12,Math.ceil(distance/20)));for(let i=0;i<count;i++){const from={x:a.x+(previous.x-a.x)*i/count,y:a.y+(previous.y-a.y)*i/count},to={x:a.x+(previous.x-a.x)*(i+1)/count,y:a.y+(previous.y-a.y)*(i+1)/count};sim.emit(from,to,{x:velocity.x*2.2*Math.min(.05,(previous.t-a.t)/1000)/STEP/count,y:velocity.y*2.2*Math.min(.05,(previous.t-a.t)/1000)/STEP/count})}if(!sim.reduced){trail.push({x:previous.x,y:previous.y,age:0});if(trail.length>12)trail.shift()}}}
function frame(t){raf=0;const dt=last===null?0:Math.min(.05,(t-last)/1000);last=t;acc+=dt;input();let n=0;while(acc>=STEP&&n++<6){if(pulse>0){pulse-=STEP;const p=sim.point(sim.branches[3],.6);sim.emit({x:p.x-45,y:p.y+50},{x:p.x+25,y:p.y-40},{x:1150,y:-650})}sim.step();for(const p of trail)p.age+=STEP;trail=trail.filter(p=>p.age<.45);acc-=STEP}render();if(pointer!==null||pulse>0||sim.active||trail.length)wake();else{last=null;acc=0;for(const b of sim.branches){b.theta=b.omega=0}sim.transform();for(const l of sim.leaves)if(l.state==='attached')Object.assign(l,sim.anchor(l));render();}}
function render(){
 ctx.clearRect(0,0,width,height);ctx.save();ctx.translate(ox,oy);ctx.scale(scale,scale);
 ctx.save();ctx.translate(454,747);ctx.scale(1,.16);const shadow=ctx.createRadialGradient(0,0,2,0,0,95);shadow.addColorStop(0,'rgba(105,106,74,.10)');shadow.addColorStop(1,'rgba(105,106,74,0)');ctx.fillStyle=shadow;ctx.fillRect(-95,-95,190,190);ctx.restore();
 // Back leaves remain independently removable, including while growing.
 for(const l of sim.leaves)if(['attached','loosening','growing'].includes(l.state)&&l.layer==='back')leaf(l);
 for(const b of sim.branches)drawBranch(b);
 for(const l of sim.leaves){if(!['attached','loosening','growing'].includes(l.state)||l.layer==='back')continue;const b=sim.branches[l.branch],p=sim.point(b,l.t);ctx.strokeStyle='rgba(111,121,76,.28)';ctx.lineWidth=.35;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(l.x,l.y);ctx.stroke();leaf(l)}
 for(const l of sim.leaves)if(!['attached','loosening','growing','gone'].includes(l.state))leaf(l);
 if(trail.length>1){ctx.beginPath();ctx.moveTo(trail[0].x,trail[0].y);for(const p of trail)ctx.lineTo(p.x,p.y);ctx.strokeStyle=`rgba(135,151,113,${Math.max(0,.14*(1-trail[0].age/.45))})`;ctx.lineWidth=1;ctx.stroke()}ctx.restore();
}
function point(c,t){const u=1-t;return{x:u*u*u*c[0][0]+3*u*u*t*c[1][0]+3*u*t*t*c[2][0]+t*t*t*c[3][0],y:u*u*u*c[0][1]+3*u*u*t*c[1][1]+3*u*t*t*c[2][1]+t*t*t*c[3][1]}}
function drawBranch(b){
 ctx.save();ctx.translate(b.origin.x,b.origin.y);ctx.rotate(b.angle);
 if(!b.renderOutline){const sides=[[],[]];for(let i=0;i<=32;i++){const t=i/32,p=point(b.c,t),q=point(b.c,Math.min(1,t+.001)),r=point(b.c,Math.max(0,t-.001)),a=Math.atan2(q.y-r.y,q.x-r.x)+Math.PI/2;const radius=b.width*.5*Math.pow(1-t,.8)+.3;for(let side=0;side<2;side++){const sign=side?1:-1;sides[side].push({x:p.x+Math.cos(a)*radius*sign,y:p.y+Math.sin(a)*radius*sign})}}
 const outline=new Path2D();outline.moveTo(sides[0][0].x,sides[0][0].y);for(const p of [...sides[0].slice(1),...sides[1].reverse()])outline.lineTo(p.x,p.y);outline.closePath();b.renderOutline=outline;}const outline=b.renderOutline;
 const tone=ctx.createLinearGradient(-b.width,0,b.width,0);tone.addColorStop(0,'#716e58');tone.addColorStop(.45,'#a19a7f');tone.addColorStop(.75,'#8d876e');tone.addColorStop(1,'#77735f');ctx.fillStyle=tone;ctx.fill(outline);
 if(b.width>5){ctx.clip(outline);for(let i=0;i<9;i++){ctx.strokeStyle=i%2?'rgba(222,212,172,.3)':'rgba(78,77,61,.20)';ctx.lineWidth=.5+(i%3)*.4;ctx.beginPath();for(let j=0;j<16;j++){const t=j/15,p=point(b.c,t),x=p.x+Math.sin(j*.7+i)*2+(i-4)*b.width/10;j?ctx.lineTo(x,p.y):ctx.moveTo(x,p.y)}ctx.stroke()}}ctx.restore();
}
function leaf(l){ctx.save();ctx.globalAlpha=l.alpha*(l.layer==='back'?.7:1);ctx.translate(l.x,l.y);ctx.rotate(l.angle);ctx.scale(leafScale*(l.layer==='back'?.92:1),leafScale*(l.layer==='back'?.92:1));if(l.state==='growing'&&!sim.reduced){const g=l.growth*l.growth*(3-2*l.growth);ctx.scale(g,g)}if(l.state==='falling'&&!sim.reduced)ctx.scale(.62+.38*Math.abs(Math.cos(l.age*(l.id%5===0?3.2:1.8))),1);const im=leafTones[l.sprite][l.tone]||sprites[l.sprite];if(im){const w=l.size,h=l.size*im.height/im.width;ctx.drawImage(im,-w*.5,-h*.85,w,h)}else{ctx.fillStyle=l.id%3?'#a5ad73':'#cfba72';ctx.beginPath();ctx.moveTo(0,0);ctx.bezierCurveTo(-12,-8,-8,-18,0,-24);ctx.bezierCurveTo(13,-15,13,-8,0,0);ctx.fill()}ctx.restore()}
document.querySelector('#breeze').addEventListener('click',()=>{sim.beginGesture();pulse=.65;wake()});
 document.querySelector('#reset').addEventListener('click',()=>{finish();sim.reset();sim.setReduced(media.matches);pulse=0;trail=[];last=null;acc=0;wake()});
 media.addEventListener('change',e=>{sim.setReduced(e.matches);trail=[];wake()});
 document.addEventListener('visibilitychange',()=>{if(document.hidden){finish();cancelAnimationFrame(raf);raf=0;last=null;acc=0;sim.wind=[];pulse=0;trail=[]}else wake()});new ResizeObserver(resize).observe(canvas);resize();
